home.code:
// Edit me and press Run.
world 1-1 {
  coin purse = 0
  run i from 1 to 5 {
    power_up purse by 10
    wahoo("Block ", i, ": ", purse, " coins")
  }
  question purse >= 50 {
    wahoo("1-UP!")
  }
}

lex.code:
// Comments and spaces vanish.
coin lives = 3
question lives <= 0 {
  wahoo("Game over")
}

opt.code:
pipe seconds(minutes: coins) -> coins {
  flag minutes * 60
}

world 1-1 {
  coin time = 2 * 60 + 30
  question 1 < 2 {
    wahoo("Time left: ", time + 0)
  } else {
    wahoo("never shown")
  }
  bounce goomba {
    wahoo("never runs")
  }
  wahoo(seconds(3) * 1)
}
